window.AUTH=window.AUTH||{};window.AUTH["24-20"]={"d":"24-20","id":"2024/24-20","n":"Fuld v. Palestine Liberation Organization","briefs":[{"k":"petitioner","label":"Brief of petitioners Miriam Fuld, et al.","date":"2025-01-28","url":"https://www.supremecourt.gov/DocketPDF/24/24-20/341546/20250130181113668_Fuld%20v.%20PLO%20No.%2024-20%20-%20Brief%20for%20Fuld%20Petitioners.pdf","side":"pet","n":73},{"k":"petitioner","label":"Brief of petitioner the United States","date":"2025-01-28","url":"https://www.supremecourt.gov/DocketPDF/24/24-20/341540/20250203125156559_24-20tsUnitedStates.pdf","side":"pet","n":85},{"k":"respondent","label":"Brief of respondents Palestine Liberation Organization, et al.","date":"2025-02-28","url":"https://www.supremecourt.gov/DocketPDF/24/24-20/350957/20250228132014273_Fuld-Sokolow%20%20Merits%20Brief%20and%20%20Appendix.pdf","side":"res","n":84},{"k":"reply","label":"Reply of petitioner United States","date":"2025-03-21","url":"https://www.supremecourt.gov/DocketPDF/24/24-20/352682/20250321114653253_24-20rbUnitedStates.pdf","side":"pet","n":47},{"k":"reply","label":"Reply of petitioners Miriam Fuld, et al.","date":"2025-03-21","url":"https://www.supremecourt.gov/DocketPDF/24/24-20/352706/20250321122923124_24-20--Fuld%20Merits%20Reply%20Brief%2003-21%20rtf.pdf","side":"pet","n":45}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/606us1r52_3eah.pdf","tr":true,"items":[{"t":"case","label":"Abitron Austria GmbH v. Hetronic Int’l, Inc.","cite":"600 U.S. 412","y":2023,"id":"2022/21-1043","sc":1,"sum":"Applying the presumption against extraterritoriality, two provisions of the Lanham Act that prohibit trademark infringement—15 U. S. C. §1114(1)(a) and §1125(a)(1)—are not extraterritorial and extend only to claims where the infringing “use in commerce” is domestic.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28-29","2":"50"}},{"t":"case","label":"Addington v. Texas","cite":"441 U.S. 418","y":1979,"id":"1978/77-5992","sc":1,"sum":"The Court held that the standard of proof required in a civil case involving involuntary commitment to a mental health facility must be higher than a preponderance of the evidence, but that the “beyond a reasonable doubt” standard was not constitutionally required.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Albright v. Oliver","cite":"510 U.S. 266","y":1994,"id":"1993/92-833","sc":1,"sum":"The Court ruled that Section 1983 relief for prosecution without probable cause is only valid if the prosecuted party claims Fourth Amendment (pretrial rights) violations.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Baker v. Baker, Eccles & Co.","cite":"242 U.S. 394","y":1917,"id":"scdb/1916-206","sc":1,"op":1,"sum":"The rule that the personal estate of an intestate has its situs at his domicile, and is subject to be administered and distributed according to the domiciliary laws, is merely a rule of the common law, which the States may adopt, modify or reject, as their policies dictate.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Birchfield v. North Dakota","cite":"579 U.S. 438","y":2016,"id":"2015/14-1468","sc":1,"sum":"The Court determined that warrantless blood tests incident to an arrest for drunk driving violate the Fourth Amendment, but warrantless breath tests incident to an arrest for drunk driving do not.","sumSrc":"Oyez","by":{"0":"42","4":"17"}},{"t":"case","label":"Washington ex rel. Bond & Goodwin & Tucker v. Superior Ct. of Wash.","cite":"289 U.S. 361","y":1933,"id":"scdb/1932-080","sc":1,"op":1,"sum":"1. A State may -provide, among the conditions upon which a foreign corporation may be admitted to do local business, that if the corporation withdraw from the State and fail to maintain a local agency for receiving service of process, service may be made on a designated state official.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Bristol-Myers Squibb Co. v. Superior Ct. of Cal.","cite":"582 U.S. 255","y":2017,"id":"2016/16-466","sc":1,"op":5,"sum":"The Court determined that, when the plaintiffs’ claims would have been exactly the same even if the defendant had no forum state contacts, there is no basis for specific jurisdiction because the case does not sufficiently arise out of or relate to the defendant’s forum activities.","sumSrc":"Oyez","by":{"0":"28, 29, 30","1":"21, 32","4":"8, 12"}},{"t":"case","label":"Burnet v. Brooks","cite":"288 U.S. 378","y":1933,"id":"scdb/1932-118","sc":1,"op":3,"ar":1,"sum":"BURNET v. BROOKS. (1) That bonds of foreign governments and of foreign and domestic corporations and stock of foreign corporations, belonging to a nonresident alien but kept in this country at the time of his death, should be included in the computation. Pp. 386, 406. (2) A local cash deposit belonging to the decedent should likewise be included if not \"deposited with any person carrying on the banking business\" and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","1":"32, 33","4":"8"}},{"t":"case","label":"Burnham v. Superior Ct. of Cal.","cite":"495 U.S. 604","y":1990,"id":"1989/89-44","sc":1,"ar":1,"sum":"The Court held that states have jurisdiction over nonresidents within their borders.","sumSrc":"Oyez","by":{"0":"35, 44","1":"23, 28","3":"17"}},{"t":"case","label":"Canada Malting Co. v. Patterson S.S.","cite":"285 U.S. 413","y":1932,"id":"scdb/1931-048","sc":1,"sum":"1. In a suit in admiralty between foreigners it is ordinarily within the discretion of the District Court to refuse to retain jurisdiction; and the exercise of its discretion will not be disturbed unless abused.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"(iv) Cases—Continued Chapman v. United States","cite":"500 U.S. 453","y":1991,"id":"1990/90-5744","sc":1,"sum":"A pure dose of the hallucinogenic drug LSD is so small that it must be sold to retail customers in a \"carrier\" created by dissolving pure LSD and, inter alia, spraying the resulting solution on paper. That paper is then cut into \"one-dose\" squares, which users swallow, lick, or drop into a beverage to release the drug. Petitioners were convicted in the District Court of selling 10 sheets (1,000 doses) of blotter …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Charter Shipping Co. v. Bowring, Jones & Tidy","cite":"281 U.S. 515","y":1930,"id":"scdb/1929-087","sc":1,"sum":"1. The retention of jurisdiction of a suit in admiralty between foreigners is within the discretion of the District Court, and the exercise of that discretion may not be disturbed unless abused.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"College Savings Bank v. Fla. Prepaid Postsecondary Educ. Expense Bd.","cite":"527 U.S. 666","y":1999,"id":"1998/98-149","sc":1,"sum":"The Court held that \"the federal courts are without jurisdiction to entertain this suit against an arm of the State of Florida.\" Justice Scalia concluded that \"the sovereign immunity of the State of Florida was neither validly abrogated by the Trademark Remedy Clarification Act, nor voluntarily waived by the State's activities in interstate commerce.\" Writing for the dissenting minority, Justice Stephen G. Breyer expressed the view that Congress possesses the authority to abrogate a state's sovereign immunity where necessary and proper to the exercise of a congressional power under the Constitution's Article I. Justice John Paul Stevens filed his own dissenting opinion and joined that of Justice Breyer.","sumSrc":"Oyez","by":{"0":"41, 42","1":"16, 39, 40","2":"10, 12-14, 21-23, 26, 41","3":"7, 21","4":"18, 19"}},{"t":"case","label":"Collins v. Virginia","cite":"584 U.S. 586","y":2018,"id":"2017/16-1027","sc":1,"op":2,"sum":"The Court held that a police officer cannot, under the Fourth Amendment, enter private property in order to conduct a warrantless search of a vehicle parked a few feet from the house.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Colorado v. Connelly","cite":"479 U.S. 157","y":1986,"id":"1986/85-660","sc":1,"sum":"The Court held that because the taking of Connelly's statements as evidence did not involve any element of governmental coercion, no violation of the Due Process Clause occurred. The Court argued that suppressing statements in cases where suspects were not coerced would have no deterrent effect on future violations of the Constitution by the police.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Cook v. Tait","cite":"265 U.S. 47","y":1924,"id":"scdb/1923-130","sc":1,"op":1,"ar":1,"sum":"Bonds, 1 Wall. 300; Dewey v. Dds Moines, 173 U. S. 193; De Lima v. Bidwell, 182 U. S. 1; United States v. Hayward, 2 Gall. 485; St. Louis v. The Ferry Co., 11 Wall. 423; Tappan.v.Merchants'NationalBank, 19 Wall: 490; Louisville Ferry Co. v. Kentucky, 188 U. S. 385; Union RefrigeratorTransit Co. v. Kentucky, 199'U. S. 194. (1) The subject of the tax is the right to the rents anmdprofits from the property realized in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","4":"8"}},{"t":"case","label":"Corbitt v. New Jersey","cite":"439 U.S. 212","y":1978,"id":"1978/77-5903","sc":1,"sum":"Under the New Jersey homicide statutes, life imprisonment is the mandatory punishment for defendants convicted by a jury of first-degree murder, while a term of not more than 30 years is the punishment for second-degree murder. Trials to the court and guilty pleas are not allowed in murder cases, but a plea of non vult is allowed. If such a plea is accepted, the judge need not decide whether the murder is first or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Daimler AG v. Bauman","cite":"571 U.S. 117","y":2014,"id":"2013/11-965","sc":1,"op":1,"ar":3,"sum":"The Court held the judiciary did not have jurisdiction over DaimlerChrysler AG in California because the conduct in question was not in the state.","sumSrc":"Oyez","by":{"0":"7","1":"8, 10","2":"42","4":"13"}},{"t":"case","label":"Denezpi v. United States","cite":"596 U.S. 591","y":2022,"id":"2021/20-7622","sc":1,"sum":"The Double Jeopardy Clause does not bar successive prosecutions of distinct offenses arising from a single act, even if a single sovereign prosecutes them.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"22"}},{"t":"case","label":"Douglass v. Nippon Yusen Kabushiki Kaisha","cite":"46 F.4th 226","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/46/226/","op":1,"ar":1,"by":{"0":"33","1":"45","2":"49","4":"9"}},{"t":"case","label":"EEOC v. Arabian Am. Oil Co.","cite":"499 U.S. 244","y":1991,"id":"1990/89-1838","sc":1,"op":1,"sum":"Title VII does not apply extraterritorially to regulate the employment practices of United States firms that employ American citizens abroad. Petitioners' evidence, while not totally lacking in probative value, falls short of demonstrating the clearly expressed affirmative congressional intent that is required to overcome the well-established presumption against statutory extraterritoriality.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31","1":"33"}},{"t":"case","label":"Ford Motor Co. v. Mont. Eighth Jud. Dist. Ct.","cite":"592 U.S. 351","y":2021,"url":"https://supreme.justia.com/cases/federal/us/592/351/","sc":1,"op":5,"sum":"Recognizing the “signifcant interests” of a forum State in “providing [its] residents with a convenient forum for redressing injuries inficted by out-of-state actors” (internal quotation marks omitted).","sumSrc":"opinion","by":{"0":"29, 40, 42, 43","2":"15-16, 26","4":"2, 12"}},{"t":"case","label":"Gamble v. United States","cite":"587 U.S. 678","y":2019,"id":"2018/17-646","sc":1,"op":3,"sum":"Recognizing interest of United States in prosecuting “the killing of an American abroad . . . in [U. S.] courts”.","sumSrc":"opinion","by":{"0":"22, 31","2":"55","4":"13"}},{"t":"case","label":"Hanson v. Denckla","cite":"357 U.S. 235","y":1958,"id":"1957/107","sc":1,"op":2,"sum":"While domiciled in Pennsylvania, a woman executed in Delaware a revocable deed of trust making a Delaware trust company trustee of certain securities, reserving the income for life and providing that the remainder should be paid to such parties as she should appoint by inter vivos or testamentary instrument. Later, after becoming domiciled in Florida, where she remained until her death, she executed (1) an inter …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","4":"8"}},{"t":"case","label":"Healy v. Beer Inst., Inc.","cite":"491 U.S. 324","y":1989,"id":"1988/88-449","sc":1,"sum":"Connecticut's beer-price-affirmation statute violates the Commerce Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31","1":"33"}},{"t":"case","label":"Hess v. Pawlowski","cite":"274 U.S. 352","y":1927,"id":"scdb/1926-076","sc":1,"by":{"0":"44","1":"24, 25","2":"24","3":"6, 10, 11"}},{"t":"case","label":"Holder v. Humanitarian L. Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"op":5,"ar":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"0":"22","1":"36-38","2":"45","3":"18, 21"}},{"t":"case","label":"Insurance Corp. of Ireland v. Compagnie des Bauxites de Guinee","cite":"456 U.S. 694","y":1982,"id":"1981/81-440","sc":1,"op":1,"ar":3,"sum":"Federal Rule of Civil Procedure 37(b)(2)(A) provides that a district court, as a sanction for failure to comply with discovery orders, may enter \"[ain order that the matters regarding which the [discovery] order was made or any other designated facts shall be taken to be established for the purposes of the action in accordance with the claim of the party obtaining the order.\" Asserting diversity jurisdiction, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36, 37, 39, 42","1":"15, 23-25, 39, 40, 42","2":"44, 69","3":"4, 5, 8, 14","4":"2, 15, 18"}},{"t":"case","label":"Int’l Shoe Co. v. Washington","cite":"326 U.S. 310","y":1945,"id":"scdb/1945-002","sc":1,"op":5,"sum":"Activities within a State of salesmen in the employ of a foreign corporation, exhibiting samples of merchandise and soliciting orders from prospective buyers to be accepted or rejected by the corporation at a point outside the State, were systematic and continuous, and resulted in a large volume of interstate business. A statute of the State requires employers to pay into the state unemployment compensation fund a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28, 39","1":"19, 21, 22, 26, 29, 34","2":"15","3":"4-6"}},{"t":"case","label":"J. McIntyre Mach., Ltd. v. Nicastro","cite":"564 U.S. 873","y":2011,"id":"2010/09-1343","sc":1,"op":5,"sum":"The Court held that a consumer cannot sue a foreign manufacturer in state court over a product that the foreign company marketed and sold in the United States.","sumSrc":"Oyez","by":{"0":"30, 42","1":"32","4":"2"}},{"t":"case","label":"Jesner v. Arab Bank PLC","cite":"584 U.S. 241","y":2018,"id":"2017/16-499","sc":1,"op":4,"sum":"The Court held that the Alien Tort Statute does not permit lawsuits against corporations.","sumSrc":"Oyez","by":{"0":"31","1":"37","2":"50","4":"11"}},{"t":"case","label":"Mallory v. Norfolk S. Ry. Co.","cite":"266 A.3d 542","y":2021,"court":"Pa.","url":"https://www.courtlistener.com/c/A.3d/266/542/","by":{"0":"37"}},{"t":"case","label":"Mallory v. Norfolk S. Ry. Co.","cite":"600 U.S. 122","y":2023,"id":"2022/21-1168","sc":1,"op":1,"sum":"A Pennsylvania law requiring out-of-state companies that register to do business in Pennsylvania to agree to appear in Pennsylvania courts on “any cause of action” against them comports with the Due Process Clause under Pennsylvania Fire Ins. Co. of Philadelphia v. Gold Issue Mining & Milling Co., 243 U. S. 93 (1917).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"5, 14, 15, 33, 34, 35, 37, 38, 39, 42","1":"44","2":"2, 9-10, 13-14, 17-18, 24-25, 27, 38, 41, 47-48, 51","3":"3, 6, 7, 9, 15","4":"2, 14, 15, 16, 19"}},{"t":"case","label":"Missouri v. McNeely","cite":"569 U.S. 141","y":2013,"id":"2012/11-1425","sc":1,"sum":"The Court held that the Fourth Amendment protects against the warrantless taking of a blood sample under exigent circumstances.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Nat’l R.R. Passenger Corp. v. Atchison Topeka & Santa Fe Ry. Co.","cite":"470 U.S. 451","y":1985,"id":"1984/83-1492","sc":1,"sum":"The Rail Passenger Service Act of 1970 (Act or RPSA) was enacted in an attempt to revive the failing intercity passenger train industry. For this purpose the Act established the National Railroad Passenger Corporation (Amtrak), a private, for-profit corporation, authorized to operate, or contract with private railroads for the operation of, intercity rail passenger service. Most private railroads offering such …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 22"}},{"t":"case","label":"North Carolina v. Alford","cite":"400 U.S. 25","y":1970,"id":"1970/14","sc":1,"sum":"The Supreme Court held that there was no constitutional violation where the defendant concluded based on competent counsel that it was in his best interest to plead guilty. The court saw no difference between a defendant who maintains his innocence with a plea bargain and one who admits to the crime.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Oregon v. Elstad","cite":"470 U.S. 298","y":1985,"id":"1984/83-773","sc":1,"sum":"In a 6-to-3 decision, the Court held that while Miranda required that unwarned admissions must be suppressed, subsequent statements, if made knowingly and voluntarily, need not be. The Court held that \". . .the mere fact that a suspect has made an unwarned admission does not warrant a presumption of compulsion.\" The Court also noted that police officers were ill-equipped to determine when \"custody\" legally begins.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Panama R.R. Co. v. Napier Shipping Co.","cite":"166 U.S. 280","y":1897,"id":"scdb/1896-139","sc":1,"sum":"The libel in this case was dismissed by the tri?.l court. The judgment of that court was reversed by the Court of Appeals, and the case was remanded for assessment of damages. After assessment and decree it was again taken to the Court of Appeals, where the decree of assessment was affirmed, whereupon a writ of certiorari from this court was granted. Held, that, upon such writ, the entire case was before this court …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Penn. Fire Ins. Co. v. Gold Issue Mining Co.","cite":"243 U.S. 93","y":1917,"id":"scdb/1916-159","sc":1,"sum":"A fire insurance company, to obtain a license to do business in Missouri, filed with the Superintendent of the Insurance Department of that State, under Missouri Rev. Stats., 1909, § 7042, a power of attorney consenting that service of process on him should be deemed personal service on the company so long as it should have any liabilities outstanding in the State. The Missouri Supreme Court, construing the statute, …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"35","1":"23-25, 44","2":"25","3":"7"}},{"t":"case","label":"Picquet v. Swan","cite":"19 F. Cas. 609","y":1828,"court":"C.C.D. Mass.","url":"https://www.courtlistener.com/c/F.%20Cas./19/609/","op":4,"ar":3,"by":{"0":"4, 16, 25","2":"59-61","4":"5, 6, 7"}},{"t":"case","label":"Principality of Monaco v. Mississippi","cite":"292 U.S. 313","y":1934,"id":"scdb/1933-124","sc":1,"op":1,"sum":"1. This Court has no jurisdiction of a suit brought by a foreign State against a State of the Union without her consent. Pp. 320, 330.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Riverside & Dan River Cotton Mills v. Menefee","cite":"237 U.S. 189","y":1915,"id":"scdb/1914-076","sc":1,"sum":"To condemn without á hearing is repugnant to the due process clause of the Fourteenth-Amendment.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"RJR Nabisco, Inc. v. Eur. Cmty.","cite":"579 U.S. 325","y":2016,"id":"2015/15-138","sc":1,"ar":2,"sum":"The Court held that some sections of the Racketeer Influenced Corrupt Organizations (RICO) statute can apply extraterritorially because Congress clearly based them on predicate offenses that can occur outside of the United States.","sumSrc":"Oyez","by":{"0":"29","4":"9"}},{"t":"case","label":"Shatsky v. Palestine Liberation Org.","cite":"955 F.3d 1016","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/955/1016/","sum":"Holding alleged “martyr payments” did not confer specific jurisdiction.","sumSrc":"brief:2","by":{"0":"40","1":"8","2":"6, 16, 29, 69"}},{"t":"case","label":"Sokolow v. Palestine Liberation Org.","cite":"138 S. Ct. 1438","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./138/1438/","sc":1,"by":{"0":"10"}},{"t":"case","label":"Sokolow v. Palestine Liberation Org.","cite":"140 S. Ct. 2714","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/2714/","sc":1,"by":{"0":"10"}},{"t":"case","label":"South Dakota v. Neville","cite":"459 U.S. 553","y":1983,"id":"1982/81-1453","sc":1,"sum":"A South Dakota statute permits a person suspected of driving while intoxicated to refuse to submit to a blood-alcohol test, but authorizes revocation of the driver's license of a person so refusing the test and permits such refusal to be used against him at trial. When respondent was arrested by police officers in South Dakota for driving while intoxicated, the officers asked him to submit to a blood-alcohol test …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","4":"17"}},{"t":"case","label":"St. Clair v. Cox","cite":"106 U.S. 350","y":1882,"id":"scdb/1882-065","sc":1,"op":1,"by":{"0":"35, 44"}},{"t":"case","label":"Turner v. Rogers","cite":"564 U.S. 431","y":2011,"id":"2010/10-10","sc":1,"op":4,"sum":"The Court held that a defendant facing incarceration for civil contempt does not have a constitutional right to a court-appointed attorney under the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"United States v. Arthrex, Inc.","cite":"594 U.S. 1","y":2021,"id":"2020/19-1434","sc":1,"sum":"The unreviewable authority wielded by Administrative Patent Judges during inter partes review is incompatible with their appointment by the Secretary of Commerce to an inferior office; the judgment of the Federal Circuit is vacated, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20"}},{"t":"case","label":"United States v. Bennett","cite":"232 U.S. 299","y":1914,"id":"scdb/1913-215","sc":1,"op":1,"sum":"The rule of interpretation that where there are two possible constructions of a statute, one of which will give rise to grave doubts of its constitutionality and the other avoids such question, the latter will be adopted, is based on the existence of both conditions as to more than one construction and doubt and is not applicable where neither of those conditions exists.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27-28","4":"8"}},{"t":"case","label":"United States v. Carlton","cite":"512 U.S. 26","y":1994,"id":"1993/92-1941","sc":1,"sum":"The 1987 amendment's retroactive application to Carlton's 1986 transactions does not violate due process. Under the applicable standard, a tax statute's retroactive application must be supported by a legitimate legislative purpose furthered by rational means. See, e. g., Pension Benefit GuarantyCorporationv. R. A. Gray & Co., 467 U. S. 717, 729-730. Here, Congress' purpose in enacting the 1987 amendment was neither …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"United States v. Epskamp","cite":"832 F.3d 154","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/832/154/","by":{"0":"32","4":"10"}},{"t":"case","label":"United States v. Iossifov","cite":"45 F.4th 899","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/45/899/","by":{"0":"32"}},{"t":"case","label":"United States v. Murillo","cite":"826 F.3d 152","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/826/152/","by":{"0":"32","4":"10"}},{"t":"case","label":"United States v. Palestine Liberation Org.","cite":"695 F. Supp. 1456","y":1988,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./695/1456/","by":{"0":"43","2":"5, 37, 73-74"}},{"t":"case","label":"United States v. Perlaza","cite":"439 F.3d 1149","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/439/1149/","by":{"0":"32"}},{"t":"case","label":"United States v. Pink","cite":"315 U.S. 203","y":1942,"id":"1940-1955/315us203","sc":1,"op":1,"sum":"The Court required New York to release the assets. Justice Douglas affirmed Justice Sutherland's reasoning in Belmont and argued that New York could not \"rewrite our foreign policy to conform to its own domestic policies. Power over external affairs . . . is vested in the national government exclusively.\".","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"United States v. Rafoi","cite":"60 F.4th 982","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/60/982/","by":{"0":"32"}},{"t":"case","label":"United States v. Vaello Madero","cite":"596 U.S. 159","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/159/","sc":1,"by":{"0":"20"}},{"t":"case","label":"Verlinden B.V. v. Central Bank of Nigeria","cite":"461 U.S. 480","y":1983,"id":"1982/81-920","sc":1,"op":1,"sum":"The Supreme Court held that the FSIA does not violate Article III. The FSIA was a valid exercise of Congress’ power to regulate foreign commerce. On remand, the court of appeals should consider whether Central Bank is entitled to sovereign immunity.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Wellness Int’l Network, Ltd. v. Sharif","cite":"575 U.S. 665","y":2015,"id":"2014/13-935","sc":1,"sum":"The Court held that claims that would normally be adjudicated by an Article III court can be adjudicated in a non-Article III court as long as the parties knowingly and voluntarily consent.","sumSrc":"Oyez","by":{"0":"40","2":"20","4":"1"}},{"t":"case","label":"World-Wide Volkswagen Corp. v. Woodson","cite":"444 U.S. 286","y":1980,"id":"1979/78-1078","sc":1,"op":7,"sum":"The Supreme Court held that a state court could only exercise in personam jurisdiction over a non-resident defendant when that defendant has “minimum contacts” with the state. In this case, the only contact with Oklahoma was the accident.","sumSrc":"Oyez","by":{"0":"4-5, 30","1":"26, 32"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"0":"17"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"i, 3, 4, 5, 10, 12, 13, 14, 16, 17, 20, 21, 22, 23, 27, 28, 29, 30, 32, 33, 42","2":"1, 8, 14, 15, 17, 26, 35, 39, 40","3":"1, 3, 4, 14, 16, 17, 22"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"0":"4, 10, 14, 16, 23, 27, 29, 33, 36, 37","3":"1, 3-5, 8, 13, 14, 16"}},{"t":"usc","label":"18 U.S.C. § 981","url":"https://www.law.cornell.edu/uscode/text/18/981","subs":["(a)(1)(G)(i)"],"by":{"0":"7"}},{"t":"usc","label":"22 U.S.C. § 2378b","url":"https://www.law.cornell.edu/uscode/text/22/2378b","subs":["(a)","(b)"],"stext":{"head":"§2378b. Limitation on assistance to the Palestinian Authority","paras":[[0,"(a) Limitation"],[0,"Assistance may be provided under this chapter to the Hamas-controlled Palestinian Authority only during a period for which a certification described in subsection (b) is in effect."],[0,"(b) Certification"],[0,"A certification described in subsection (a) is a certification transmitted by the President to Congress that contains a determination of the President that—"],[1,"(1) no ministry, agency, or instrumentality of the Palestinian Authority is effectively controlled by Hamas, unless the Hamas-controlled Palestinian Authority has—"],[2,"(A) publicly acknowledged the Jewish state of Israel's right to exist; and"],[2,"(B) committed itself and is adhering to all previous agreements and understandings with the United States Government, with the Government of Israel, and with the international community, including agreements and understandings pursuant to the Performance-Based Roadmap to a Permanent Two-State Solution to the Israeli-Palestinian Conflict (commonly referred to as the \"Roadmap\"); and"],[1,"(2) the Hamas-controlled Palestinian Authority has made demonstrable progress toward—"],[2,"(A) completing the process of purging from its security services individuals with ties to terrorism;"],[2,"(B) dismantling all terrorist infrastructure within its jurisdiction, confiscating unauthorized weapons, arresting and bringing terrorists to justice, destroying unauthorized arms factories, thwarting and preempting terrorist attacks, and fully cooperating with Israel's security services;"],[2,"(C) halting all anti-American and anti-Israel incitement in Palestinian Authority-controlled electronic and print media and in schools, mosques, and other institutions it controls, and replacing educational materials, including textbooks, with materials that promote peace, tolerance, and coexistence with Israel;"],[2,"(D) ensuring democracy, the rule of law, and an independent judiciary, and adopting other reforms such as ensuring transparent and accountable governance; and"],[2,"(E) ensuring the financial transparency and accountability of all government ministries and operations."],[0,"(c) Recertifications"],[0,"Not later than 90 days after the date on which the President transmits to Congress an initial certification under subsection (b), and every six months thereafter—"],[1,"(1) the President shall transmit to Congress a recertification that the conditions described in subsection (b) are continuing to be met; or"],[1,"(2) if the President is unable to make such a recertification, the President shall transmit to Congress a report that contains the reasons therefor."],[0,"(d) Congressional notification"],[0,"Assistance made available under this chapter to the Palestinian Authority may not be provided until 15 days after the date on which the President has provided notice thereof to the appropriate congressional committees in accordance with the procedures applicable to reprogramming notifications under section 2394–1(a) of this title."],[0,"(e) National security waiver"],[0,"(1) In general"],[1,"Subject to paragraph (2), the President may waive subsection (a) with respect to—"],[2,"(A) the administrative and personal security costs of the Office of the President of the Palestinian Authority;"],[2,"(B) the activities of the President of the Palestinian Authority to fulfill his or her duties as President, including to maintain control of the management and security of border crossings, to foster the Middle East peace process, and to promote democracy and the rule of law; and"],[2,"(C) assistance for the judiciary branch of the Palestinian Authority and other entities."],[0,"(2) Certification"],[1,"The President may only exercise the waiver authority under paragraph (1) after—"],[2,"(A) consulting with, and submitting a written policy justification to, the appropriate congressional committees; and"],[2,"(B) certifying to the appropriate congressional committees that—"],[3,"(i) it is in the national security interest of the United States to provide assistance otherwise prohibited under subsection (a); and"],[3,"(ii) the individual or entity for which assistance is proposed to be provided is not a member of, or effectively controlled by (as the case may be), Hamas or any other foreign terrorist organization."],[0,"(3) Report"],[1,"Not later than 10 days after exercising the waiver authority under paragraph (1), the President shall submit to the appropriate congressional committees a report describing how the funds provided pursuant to such waiver will be spent and detailing the accounting procedures that are in place to ensure proper oversight and accountability."],[0,"(4) Treatment of certification as notification of program change"],[1,"For purposes of this subsection, the certification required under paragraph (2)(B) shall be deemed to be a notification under section 2394–1 of this title and shall be considered in accordance with the procedures applicable to notifications submitted pursuant to that section."],[0,"(f) Definitions"],[0,"In this section:"],[0,"(1) Appropriate congressional committees"],[1,"The term \"appropriate congressional committees\" means—"],[2,"(A) the Committee on International Relations and the Committee on Appropriations of the House of Representatives; and"],[2,"(B) the Committee on Foreign Relations and the Committee on Appropriations of the Senate."],[0,"(2) Foreign terrorist organization"],[1,"The term \"foreign terrorist organization\" means an organization designated as a foreign terrorist organization by the Secretary of State in accordance with section 1189(a) of title 8."],[0,"(3) Palestinian Authority"],[1,"The term \"Palestinian Authority\" means the interim Palestinian administrative organization that governs part of the West Bank and all of the Gaza Strip (or any successor Palestinian governing entity), including the Palestinian Legislative Council."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/2378b?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2378b. Limitation on assistance to the Palestinian Authority","tname":"Foreign Relations and Intercourse","by":{"0":"45","1":"7, 35, 35, 35","2":"4","3":"12"}},{"t":"usc","label":"28 U.S.C. § 1738","url":"https://www.law.cornell.edu/uscode/text/28/1738","subs":["(2012)"],"by":{"0":"26"}},{"t":"law","label":"Pub. L. No. 115-253","url":"https://www.govinfo.gov/link/plaw/115/public/253","by":{"0":"7, 10","1":"10","2":"6, 37-38","3":"2, 12"}},{"t":"law","label":"Pub. L. No. 109-446","url":"https://www.govinfo.gov/link/plaw/109/public/446","by":{"0":"45"}},{"t":"law","label":"Promoting Security and Justice for Victims of Terrorism Act, Pub. L. No. 116-94","url":"https://www.govinfo.gov/link/plaw/116/public/94","by":{"0":"3, 4, 8","1":"3, 11, 21","3":"2"}},{"t":"case","label":"Adam v. Saenger","cite":"303 U.S. 59","y":1938,"id":"scdb/1937-095","sc":1,"sum":"That this question, whether regarded as of fact or of law, is a federal question arising under the Full Faith and Credit Clause and R. S. § 905, 28 U. S. C. 687, and its decision by the Texas court is reviewable here.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25","3":"8"}},{"t":"case","label":"Ashwander v. TVA","cite":"297 U.S. 288","y":1936,"id":"1900-1940/297us288","sc":1,"sum":"The Court held that Congress did not abuse its power with the TVA. Justice Hughes argued that the Wilson Dam, the location where the TVA was in the business of generating electricity, had been built originally in the interest of national defense: it produced materials involved in munitions manufacture. The government could sell excess electricity to consumers without violating the Constitution.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"578 U.S. 212","y":2016,"id":"2015/14-770","sc":1,"op":3,"sum":"The Court decided that a statute effectively directing a particular result in a single pending case does not violate the separation of powers.","sumSrc":"Oyez","by":{"1":"37","2":"68-69","3":"20-23","4":"20, 21"}},{"t":"case","label":"Biton v. Palestinian Interim Self-Gov’t Auth.","cite":"252 F.R.D. 1","y":2008,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.R.D./252/1/","by":{"1":"9"}},{"t":"case","label":"Board of Trustees v. United States","cite":"289 U.S. 48","y":1933,"id":"1900-1940/289us48","sc":1,"op":2,"sum":"Rejecting contention that state instrumentality was immune from paying import duties.","sumSrc":"opinion","by":{"1":"32"}},{"t":"case","label":"Bonet v. Texas Co. (P.R.)","cite":"308 U.S. 463","y":1940,"id":"scdb/1939-037","sc":1,"by":{"1":"46"}},{"t":"case","label":"Burger King Corp. v. Rudzewicz","cite":"471 U.S. 462","y":1985,"id":"1984/83-2097","sc":1,"op":2,"sum":"The District Court's exercise of jurisdiction pursuant to Florida's long-arm statute did not violate the Due Process Clause of the Fourteenth Amendment. Pp. 471-487. BURGER KING CORP. v. RUDZEWICZ","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26, 34","2":"15, 19, 40"}},{"t":"case","label":"Carnival Cruise Lines, Inc. v. Shute","cite":"499 U.S. 585","y":1991,"id":"1990/89-1647","sc":1,"ar":1,"sum":"The Court of Appeals erred in refusing to enforce the forumselection clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15, 24, 25","4":"15"}},{"t":"case","label":"Chicago Life Ins. Co. v. Cherry","cite":"244 U.S. 25","y":1917,"id":"scdb/1916-050","sc":1,"sum":"In an action on a sister state judgment a state court may inquire whether there was personal jurisdiction in the prior proceedings, notwithstanding the question was raised by the judgment defendant and affirmatively decided against him after full hearing both in. the trial court which rendered the judgment and in the appellate courts of the same State to which he took the case for review.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"23, 25, 30","3":"6"}},{"t":"case","label":"D.H. Overmyer Co. v. Frick Co.","cite":"405 U.S. 174","y":1972,"id":"1971/69-5","sc":1,"sum":"Justice Harry A. Blackmun wrote for a unanimous Supreme Court and held that contractual clause waiving a party's rights to prejudgment notice and hearing is not unconstitutional per se. Since Overmyer agreed to the provision for consideration and with full awareness of the legal consequences, enforcement of the waiver was not a violation of Overmyer's constitutional rights.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Doran v. Salem Inn, Inc.","cite":"422 U.S. 922","y":1975,"id":"1974/74-337","sc":1,"sum":"Three corporations (M & L, Salem, and Tim-Rob), on August 9, 1973, filed a complaint in District Court, seeking a temporary restraining order, preliminary injunction, and declaratory relief, against Doran, a law enforcement official, claiming that a North Hempstead, N. Y., ordinance proscribing topless dancing, which the corporations had provided as entertainment in their bars, violated their First and Fourteenth …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Elk Grove Unified Sch. Dist. v. Newdow","cite":"542 U.S. 1","y":2004,"id":"2003/02-1624","sc":1,"sum":"The Court held that a divorced father did not have sufficient custody of his daughter to challenge the Establishment Clause of the First Amendment on her behalf.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Ford Motor Co. v. Montana Eighth Jud. Dist. Ct.","cite":"592 U.S. 351","y":2021,"id":"2020/19-368","sc":1,"op":5,"sum":"Recognizing the “signifcant interests” of a forum State in “providing [its] residents with a convenient forum for redressing injuries inficted by out-of-state actors” (internal quotation marks omitted).","sumSrc":"opinion","by":{"1":"22, 24, 29, 32, 46","3":"14"}},{"t":"case","label":"French v. Barber Asphalt Paving Co.","cite":"181 U.S. 324","y":1901,"id":"scdb/1900-171","sc":1,"op":1,"sum":"In this case tlie court proceeds on the assumption that the legal import of the phrase “ due process of law” is the same both in the Fifth and in the Fourteenth Amendments to the Constitution of the United States; and that it cannot be supposed that it was intended by the Fourteenth Amendment to impose on the States, when exercising their powers of taxation, any more rigid or stricter curb than that imposed on.the …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"32","3":"16"}},{"t":"case","label":"Gilmore v. Palestinian Interim Self-Gov’t Auth.","cite":"675 F. Supp. 2d 104","y":2009,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/675/104/","by":{"1":"9"}},{"t":"case","label":"Hernandez v. Mesa","cite":"589 U.S. 93","y":2020,"id":"2019/17-1678","sc":1,"sum":"The Court held that the family of a Mexican teenager who was killed by a U.S. Border Patrol agent in a cross-border shooting cannot sue the agent for damages under the U.S. Constitution.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Hines v. Davidowitz","cite":"312 U.S. 52","y":1941,"id":"scdb/1940-064","sc":1,"sum":"1. Applicable legislation enacted while the case was pending on appeal will be enforced by the appellate court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Horne v. Adolph Coors Co.","cite":"684 F.2d 255","y":1982,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/684/255/","by":{"1":"34"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"1":"22, 31","3":"5"}},{"t":"case","label":"Kiobel v. Royal Dutch Petroleum Co.","cite":"569 U.S. 108","y":2013,"id":"2011/10-1491","sc":1,"sum":"The Court found that the Alien Tort Statute does not give ground for United States law to be applied extraterrestrially to other sovereign nations with their own laws.","sumSrc":"Oyez","by":{"1":"48","2":"50, 64"}},{"t":"case","label":"Klinghoffer v. S.N.C. Achille Lauro Ed Altri-Gestione Motonave Achille Lauro in Amministrazione Straordinaria","cite":"937 F.2d 44","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/937/44/","by":{"1":"7"}},{"t":"case","label":"Knox v. PLO","cite":"248 F.R.D. 420","y":2008,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.R.D./248/420/","by":{"1":"9"}},{"t":"case","label":"Kulko v. Superior Ct.","cite":"436 U.S. 84","y":1978,"id":"1977/77-293","sc":1,"sum":"The exercise of in personam jurisdiction by the California courts over appellant, a New York domiciliary, would violate the Due Process Clause of the Fourteenth Amendment. The mere act of sending a child to California to live with her mother connotes no intent to obtain nor expectancy of receiving a corresponding benefit in that State that would make fair the assertion of that State's judicial jurisdiction over …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Lightfoot v. Cendant Mortg. Corp.","cite":"580 U.S. 82","y":2017,"id":"2016/14-1055","sc":1,"op":1,"sum":"The Court determined that language in the federal charter of the Federal National Mortgage Association (Fannie Mae) that authorizes the organization to sue and be sued does not mean that federal courts have subject matter jurisdiction over any case in which Fannie Mae is a plaintiff or defendant, and the Supreme Court’s precedent in American National Red Cross v. S.G. doe not require a different result.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Livnat v. PA","cite":"851 F.3d 45","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/851/45/","op":3,"sum":"Explaining Respondents’ “headquarters, officials, and primary activities are all in the West Bank”.","sumSrc":"brief:2","by":{"1":"45, 46","2":"49"}},{"t":"case","label":"McDonald v. Mabee","cite":"243 U.S. 90","y":1917,"id":"scdb/1916-158","sc":1,"sum":"A person domiciled in Texas left the State intending to make his home elsewhere, his family residing there meanwhile. During his absence an action for money was begun against him in a Texas court. After returning and remaining for a short time, he departed finally and established a domicile in another State. The only service in the action was by publication in a newspaper after his final departure. Based on this …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Medina v. California","cite":"505 U.S. 437","y":1992,"id":"1991/90-8370","sc":1,"sum":"Before petitioner Medina's trial for, inter alia, first-degree murder, the California court granted his motion for a competency hearing pursuant to a state law that forbids a mentally incompetent person to be tried or punished, establishes a presumption of competence, and placed on petitioner the burden of proving incompetence by a preponderance of the evidence. The jury empaneled for the competency hearing found …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Morrissey v. Brewer","cite":"408 U.S. 471","y":1972,"id":"1971/71-5103","sc":1,"sum":"The Court held that due process required Iowa to include a preliminary hearing to determine probable cause for the parole revocations of Morrissey and Booker.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Old Wayne Mutual Life Ass’n v. McDonough","cite":"204 U.S. 8","y":1907,"id":"scdb/1906-193","sc":1,"sum":"A statute of Pennsylvania provides: “No insurance company not of.this State, nor its agents, shall do business in this State until it has filed with the Insurance Commissioner of this State-a written stipulation, duly authenticated by the company, agreeing that any legal process affecting the company, served on the Insurance Commissioner, or the party designated by him, or the agent specified by. the company to …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Petrowski v. Hawkeye-Security Co.","cite":"350 U.S. 495","y":1956,"id":"1955/469","sc":1,"sum":"The District Court had jurisdiction of the subject matter in this case; and respondent, by its stipulation, waived any right to assert a lack of personal jurisdiction over it. Pp. 495-496. 226 F. 2d 126, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Republic of Argentina v. Weltover, Inc.","cite":"504 U.S. 607","y":1992,"id":"1991/91-763","sc":1,"op":1,"sum":"The Court held that the District Court properly asserted jurisdiction under the FSIA.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Republic of Panama v. BCCI Holdings (Lux.) S.A.","cite":"119 F.3d 935","y":1997,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/119/935/","by":{"1":"33"}},{"t":"case","label":"Shaffer v. Heitner","cite":"433 U.S. 186","y":1977,"id":"1976/75-1812","sc":1,"sum":"Appellee, a nonresident of Delaware, filed a shareholder's derivative suit in a Delaware Chancery Court, naming as defendants a corporation and its subsidiary, as well as 28 present or former corporate officers or directors, alleging that the individual defendants had violated their duties to the corporation by causing it and its subsidiary to engage in actions (which occurred in Oregon) that resulted in corporate …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Smolik v. Philadelphia & Reading Coal & Iron Co.","cite":"222 F. 148","y":1915,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F./222/148/","by":{"1":"44"}},{"t":"case","label":"South Carolina v. Katzenbach","cite":"383 U.S. 301","y":1966,"id":"1965/22_orig","sc":1,"op":2,"sum":"The Court held that the Fifteenth Amendment is a valid constitutional basis for the Voting Rights Act of 1965.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Trinity Lutheran Church of Columbia, Inc. v. Comer","cite":"582 U.S. 449","y":2017,"id":"2016/15-577","sc":1,"op":3,"sum":"The Court determined that the exclusion of churches from an otherwise neutral and secular aid program violates the First Amendment’s guarantee of free exercise of religion.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Twitter, Inc. v. Taamneh","cite":"598 U.S. 471","y":2023,"id":"2022/21-1496","sc":1,"sum":"Plaintiffs’ allegations that the social-media-company defendants aided and abetted ISIS in its terrorist attack on a nightclub in Istanbul, Turkey fail to state a claim under 18 U. S. C. §2333(d)(2).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"8"}},{"t":"case","label":"Ungar v. PLO: 402 F.3d 274 (1st Cir.), cert. denied","cite":"546 U.S. 1034","y":2005,"url":"https://supreme.justia.com/cases/federal/us/546/1034/","sc":1,"by":{"1":"9"}},{"t":"case","label":"Vidal v. Elster","cite":"602 U.S. 286","y":2024,"id":"2023/22-704","sc":1,"sum":"The Lanham Act’s names clause—which prohibits the registration of a mark that “[c]onsists of or comprises a name . . . identifying a particular living individual except by his written consent,” 15 U. S. C. §1052(c)—does not violate the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"47"}},{"t":"case","label":"Washington State Grange v. Washington State Republican Party","cite":"552 U.S. 442","y":2008,"id":"2007/06-713","sc":1,"sum":"The Court reversed the Ninth Circuit's ruling and held the party affiliation provision constitutional. Writing for the majority, Justice Clarence Thomas explained that the state law never referred to the candidates as nominees of any particular party.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"usc","label":"22 U.S.C. § 5201","url":"https://www.law.cornell.edu/uscode/text/22/5201","subs":["(a)(2)","(a)(4)","(b)"],"stext":{"head":"§5201. Findings; determinations","paras":[[0,"(a) Findings"],[0,"The Congress finds that—"],[1,"(1) Middle East terrorism accounted for 60 percent of total international terrorism in 1985;"],[1,"(2) the Palestine Liberation Organization (hereafter in this chapter referred to as the \"PLO\") was directly responsible for the murder of an American citizen on the Achille Lauro cruise liner in 1985, and a member of the PLO's Executive Committee is under indictment in the United States for the murder of that American citizen;"],[1,"(3) the head of the PLO has been implicated in the murder of a United States Ambassador overseas;"],[1,"(4) the PLO and its constituent groups have taken credit for, and been implicated in, the murders of dozens of American citizens abroad;"],[1,"(5) the PLO covenant specifically states that \"armed struggle is the only way to liberate Palestine, thus it is an overall strategy, not merely a tactical phase\";"],[1,"(6) the PLO rededicated itself to the \"continuing struggle in all its armed forms\" at the Palestine National Council meeting in April 1987; and"],[1,"(7) the Attorney General has stated that \"various elements of the Palestine Liberation Organization and its allies and affiliates are in the thick of international terror\"."],[0,"(b) Determinations"],[0,"Therefore, the Congress determines that the PLO and its affiliates are a terrorist organization and a threat to the interests of the United States, its allies, and to international law and should not benefit from operating in the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/5201?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5201. Findings; determinations","tname":"Foreign Relations and Intercourse","by":{"1":"7, 35, 7, 7","2":"4, 37"}},{"t":"usc","label":"22 U.S.C. § 5202","url":"https://www.law.cornell.edu/uscode/text/22/5202","stext":{"head":"§5202. Prohibitions regarding PLO","paras":[[0,"It shall be unlawful, if the purpose be to further the interests of the Palestine Liberation Organization or any of its constituent groups, any successor to any of those, or any agents thereof, on or after the effective date of this chapter—"],[1,"(1) to receive anything of value except informational material from the PLO or any of its constituent groups, any successor thereto, or any agents thereof;"],[1,"(2) to expend funds from the PLO or any of its constituent groups, any successor thereto, or any agents thereof; or"],[1,"(3) notwithstanding any provision of law to the contrary, to establish or maintain an office, headquarters, premises, or other facilities or establishments within the jurisdiction of the United States at the behest or direction of, or with funds provided by the Palestine Liberation Organization or any of its constituent groups, any successor to any of those, or any agents thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/5202?type=usc&year=mostrecent&link-type=html"},"head":"§5202. Prohibitions regarding PLO","tname":"Foreign Relations and Intercourse","by":{"1":"7, 35","2":"4, 37"}},{"t":"usc","label":"18 U.S.C. § 2331","url":"https://www.law.cornell.edu/uscode/text/18/2331","subs":["(1)(C)"],"stext":{"head":"§2331. Definitions","paras":[[0,"As used in this chapter—"],[1,"(1) the term \"international terrorism\" means activities that—"],[2,"(A) involve violent acts or acts dangerous to human life that are a violation of the criminal laws of the United States or of any State, or that would be a criminal violation if committed within the jurisdiction of the United States or of any State;"],[2,"(B) appear to be intended—"],[3,"(i) to intimidate or coerce a civilian population;"],[3,"(ii) to influence the policy of a government by intimidation or coercion; or"],[3,"(iii) to affect the conduct of a government by mass destruction, assassination, or kidnapping; and"],[2,"(C) occur primarily outside the territorial jurisdiction of the United States, or transcend national boundaries in terms of the means by which they are accomplished, the persons they appear intended to intimidate or coerce, or the locale in which their perpetrators operate or seek asylum;"],[1,"(2) the term \"national of the United States\" has the meaning given such term in section 101(a)(22) of the Immigration and Nationality Act;"],[1,"(3) the term \"person\" means any individual or entity capable of holding a legal or beneficial interest in property;"],[1,"(4) the term \"act of war\" means any act occurring in the course of—"],[2,"(A) declared war;"],[2,"(B) armed conflict, whether or not war has been declared, between two or more nations; or"],[2,"(C) armed conflict between military forces of any origin;"],[1,"(5) the term \"domestic terrorism\" means activities that—"],[2,"(A) involve acts dangerous to human life that are a violation of the criminal laws of the United States or of any State;"],[2,"(B) appear to be intended—"],[3,"(i) to intimidate or coerce a civilian population;"],[3,"(ii) to influence the policy of a government by intimidation or coercion; or"],[3,"(iii) to affect the conduct of a government by mass destruction, assassination, or kidnapping; and"],[2,"(C) occur primarily within the territorial jurisdiction of the United States; and"],[1,"(6) the term \"military force\" does not include any person that—"],[2,"(A) has been designated as a—"],[3,"(i) foreign terrorist organization by the Secretary of State under section 219 of the Immigration and Nationality Act (8 U.S.C. 1189); or"],[3,"(ii) specially designated global terrorist (as such term is defined in section 594.310 of title 31, Code of Federal Regulations) by the Secretary of State or the Secretary of the Treasury; or"],[2,"(B) has been determined by the court to not be a \"military force\"."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2331?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2331. Definitions","tname":"Crimes and Criminal Procedure","by":{"1":"3, 8, 33","3":"2"}},{"t":"usc","label":"18 U.S.C. § 2333","url":"https://www.law.cornell.edu/uscode/text/18/2333","subs":["(a)"],"stext":{"head":"§2333. Civil remedies","paras":[[0,"(a) Action and Jurisdiction.—Any national of the United States injured in his or her person, property, or business by reason of an act of international terrorism, or his or her estate, survivors, or heirs, may sue therefor in any appropriate district court of the United States and shall recover threefold the damages he or she sustains and the cost of the suit, including attorney's fees."],[0,"(b) Estoppel Under United States Law.—A final judgment or decree rendered in favor of the United States in any criminal proceeding under section 1116, 1201, 1203, or 2332 of this title or section 46314, 46502, 46505, or 46506 of title 49 shall estop the defendant from denying the essential allegations of the criminal offense in any subsequent civil proceeding under this section."],[0,"(c) Estoppel Under Foreign Law.—A final judgment or decree rendered in favor of any foreign state in any criminal proceeding shall, to the extent that such judgment or decree may be accorded full faith and credit under the law of the United States, estop the defendant from denying the essential allegations of the criminal offense in any subsequent civil proceeding under this section."],[0,"(d) Liability.—"],[1,"(1) Definition.—In this subsection, the term \"person\" has the meaning given the term in section 1 of title 1."],[1,"(2) Liability.—In an action under subsection (a) for an injury arising from an act of international terrorism committed, planned, or authorized by an organization that had been designated as a foreign terrorist organization under section 219 of the Immigration and Nationality Act (8 U.S.C. 1189), as of the date on which such act of international terrorism was committed, planned, or authorized, liability may be asserted as to any person who aids and abets, by knowingly providing substantial assistance, or who conspires with the person who committed such an act of international terrorism."],[0,"(e) Use of Blocked Assets to Satisfy Judgments of U.S. Nationals.—For purposes of section 201 of the Terrorism Risk Insurance Act of 2002 (28 U.S.C. 1610 note), in any action in which a national of the United States has obtained a judgment against a terrorist party pursuant to this section, the term \"blocked asset\" shall include any asset of that terrorist party (including the blocked assets of any agency or instrumentality of that party) seized or frozen by the United States under section 805(b) of the Foreign Narcotics Kingpin Designation Act (21 U.S.C. 1904(b))."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2333?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2333. Civil remedies","tname":"Crimes and Criminal Procedure","by":{"1":"8, 29"}},{"t":"usc","label":"22 U.S.C. § 2378c-1","url":"https://www.law.cornell.edu/uscode/text/22/2378c-1","subs":["(a)"],"stext":{"head":"§2378c–1. Limitation on assistance to the West Bank and Gaza","paras":[[0,"(a) Limitation"],[0,"(1) In general"],[1,"Funds authorized to be appropriated or otherwise made available for assistance under chapter 4 of part II of the Foreign Assistance Act of 1961 (22 U.S.C. 2346 et seq.; relating to Economic Support Fund) and available for assistance for the West Bank and Gaza that directly benefits the Palestinian Authority may only be made available for such purpose if, except as provided in subsection (d), not later than 30 days after March 23, 2018, and every 180 days thereafter, the Secretary of State certifies in writing to the appropriate congressional committees that the Palestinian Authority, the Palestine Liberation Organization, and any successor or affiliated organizations—"],[2,"(A) are taking credible steps to end acts of violence against Israeli citizens and United States citizens that are perpetrated or materially assisted by individuals under their jurisdictional control, such as the March 2016 attack that killed former United States Army officer Taylor Force, a veteran of the wars in Iraq and Afghanistan;"],[2,"(B) have terminated payments for acts of terrorism against Israeli citizens and United States citizens to any individual, after being fairly tried, who has been imprisoned for such acts of terrorism and to any individual who died committing such acts of terrorism, including to a family member of such individuals;"],[2,"(C) have revoked any law, decree, regulation, or document authorizing or implementing a system of compensation for imprisoned individuals that uses the sentence or period of incarceration of an individual imprisoned for an act of terrorism to determine the level of compensation paid, or have taken comparable action that has the effect of invalidating any such law, decree, regulation, or document; and"],[2,"(D) are publicly condemning such acts of violence and are taking steps to investigate or are cooperating in investigations of such acts to bring the perpetrators to justice."],[0,"(2) Additional certification requirement"],[1,"The Secretary of State shall include in the certification required under paragraph (1) the definition of \"acts of terrorism\" that the Secretary used for purposes of making the determination in subparagraph (B) of such paragraph."],[0,"(b) Exception"],[0,"(1) In general"],[1,"Subject to paragraph (2), the limitation on assistance under subsection (a) shall not apply to—"],[2,"(A) payments made to the East Jerusalem Hospital Network;"],[2,"(B) assistance for wastewater projects not exceeding $5,000,000 in any one fiscal year; and"],[2,"(C) assistance for any other program, project, or activity that provides vaccinations to children not exceeding $500,000 in any one fiscal year."],[0,"(2) Notification"],[1,"The Secretary of State shall notify in writing the appropriate congressional committees not later than 15 days prior to making funds available for assistance under subparagraph (A), (B), or (C) of paragraph (1)."],[0,"(c) Rule of construction"],[0,"Funds withheld pursuant to this section—"],[1,"(1) shall be deemed to satisfy any similar withholding or reduction required under any other provision of law relating to the Palestinian Authority's payments for acts of terrorism; and"],[1,"(2) shall be in an amount that is not less than the total amount required by such other provision of law."],[0,"(d) Initial use and disposition of withheld funds"],[0,"(1) Period of availability"],[1,"Funds withheld pursuant to this section are authorized to remain available for an additional 2 years from the date on which the availability of such funds would otherwise have expired."],[0,"(2) Use of funds"],[1,"Funds withheld pursuant to this section may be made available for assistance for the West Bank and Gaza that directly benefits the Palestinian Authority upon a certification by the Secretary of State that the Palestinian Authority, the Palestine Liberation Organization, and any successor or affiliated organizations have met the conditions set forth in subsection (a). Except as provided in paragraph (3), such funds may not be made available for any purpose other than for assistance for the West Bank and Gaza that directly benefits the Palestinian Authority."],[0,"(3) Disposition of unused funds"],[1,"Beginning on the date that is 180 days after the last day on which the initial availability of funds withheld pursuant to this section would otherwise have expired, such funds are authorized to be made available to the Department of State for assistance under chapter 4 of part II of the Foreign Assistance Act of 1961 (22 U.S.C. 2346 et seq.; relating to Economic Support Fund) in the following manner—"],[2,"(A) 50 percent for purposes of assistance other than that deemed benefiting the Palestinian Authority; and"],[2,"(B) 50 percent for purposes other than assistance for the West Bank and Gaza."],[0,"(e) Report"],[0,"(1) In general"],[1,"If the Secretary of State is unable to certify in writing to the appropriate congressional committees that the Palestinian Authority, the Palestine Liberation Organization, and any successor or affiliated organizations have met the conditions described in subsection (a), the Secretary shall, not later than 15 days after the date on which the Secretary is unable to make such certification, submit to the appropriate congressional committees a report that contains the following:"],[2,"(A) The reasons why the Secretary was unable to certify in writing that such organizations have met such requirements."],[2,"(B) The definition of \"acts of terrorism\" that the Secretary used for purposes of making the determination in subparagraph (B) of subsection (a)(1)."],[2,"(C) The total amount of funds to be withheld."],[0,"(2) Form"],[1,"The report required by this subsection shall be submitted in unclassified form but may include a classified annex."],[0,"(f) List of criteria"],[0,"(1) In general"],[1,"Not later than 15 days after March 23, 2018, the Secretary of State shall submit to the appropriate congressional committees a list of the criteria that the Secretary uses to determine whether assistance for the West Bank and Gaza is assistance that directly benefits the Palestinian Authority for purposes of carrying out this section."],[0,"(2) Update"],[1,"The Secretary of State shall submit to the appropriate congressional committees an updated list under paragraph (1) not later than 15 days after the date on which the Secretary makes any modification to the list."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/2378c-1?type=usc&year=mostrecent&link-type=html"},"head":"§2378c–1. Limitation on assistance to the West Bank and Gaza","tname":"Foreign Relations and Intercourse","by":{"1":"8, 29, 35","3":"19"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(3)(B)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"1":"35"}},{"t":"usc","label":"18 U.S.C. § 2334","url":"https://www.law.cornell.edu/uscode/text/18/2334","subs":["(e)","(e)(1)","(e)(1)(A)","(e)(1)(B)","(e)(1)(B)(iii)","(e)(2)","(e)(3)","(e)(5)"],"stext":{"head":"§2334. Jurisdiction and venue","paras":[[0,"(a) General Venue.—Any civil action under section 2333 of this title against any person may be instituted in the district court of the United States for any district where any plaintiff resides or where any defendant resides or is served, or has an agent. Process in such a civil action may be served in any district where the defendant resides, is found, or has an agent."],[0,"(b) Special Maritime or Territorial Jurisdiction.—If the actions giving rise to the claim occurred within the special maritime and territorial jurisdiction of the United States, as defined in section 7 of this title, then any civil action under section 2333 of this title against any person may be instituted in the district court of the United States for any district in which any plaintiff resides or the defendant resides, is served, or has an agent."],[0,"(c) Service on Witnesses.—A witness in a civil action brought under section 2333 of this title may be served in any other district where the defendant resides, is found, or has an agent."],[0,"(d) Convenience of the Forum.—The district court shall not dismiss any action brought under section 2333 of this title on the grounds of the inconvenience or inappropriateness of the forum chosen, unless—"],[1,"(1) the action may be maintained in a foreign court that has jurisdiction over the subject matter and over all the defendants;"],[1,"(2) that foreign court is significantly more convenient and appropriate; and"],[1,"(3) that foreign court offers a remedy which is substantially the same as the one available in the courts of the United States."],[0,"(e) Consent of Certain Parties to Personal Jurisdiction.—"],[1,"(1) In general.—Except as provided in paragraph (2), for purposes of any civil action under section 2333 of this title, a defendant shall be deemed to have consented to personal jurisdiction in such civil action if, regardless of the date of the occurrence of the act of international terrorism upon which such civil action was filed, the defendant—"],[2,"(A) after the date that is 120 days after the date of the enactment of the Promoting Security and Justice for Victims of Terrorism Act of 2019, makes any payment, directly or indirectly—"],[3,"(i) to any payee designated by any individual who, after being fairly tried or pleading guilty, has been imprisoned for committing any act of terrorism that injured or killed a national of the United States, if such payment is made by reason of such imprisonment; or"],[3,"(ii) to any family member of any individual, following such individual's death while committing an act of terrorism that injured or killed a national of the United States, if such payment is made by reason of the death of such individual; or"],[2,"(B) after 15 days after the date of enactment of the Promoting Security and Justice for Victims of Terrorism Act of 2019—"],[3,"(i) continues to maintain any office, headquarters, premises, or other facilities or establishments in the United States;"],[3,"(ii) establishes or procures any office, headquarters, premises, or other facilities or establishments in the United States; or"],[3,"(iii) conducts any activity while physically present in the United States on behalf of the Palestine Liberation Organization or the Palestinian Authority."],[1,"(2) Applicability.—Paragraph (1) shall not apply to any defendant who ceases to engage in the conduct described in paragraphs (1)(A) and (1)(B) for 5 consecutive calendar years. Except with respect to payments described in paragraph (1)(A), no court may consider the receipt of any assistance by a nongovernmental organization, whether direct or indirect, as a basis for consent to jurisdiction by a defendant."],[1,"(3) Exception for certain activities and locations.—In determining whether a defendant shall be deemed to have consented to personal jurisdiction under paragraph (1)(B), no court may consider—"],[2,"(A) any office, headquarters, premises, or other facility or establishment used exclusively for the purpose of conducting official business of the United Nations;"],[2,"(B) any activity undertaken exclusively for the purpose of conducting official business of the United Nations;"],[2,"(C) any activity involving officials of the United States that the Secretary of State determines is in the national interest of the United States if the Secretary reports to the appropriate congressional committees annually on the use of the authority under this subparagraph;"],[2,"(D) any activity undertaken exclusively for the purpose of meetings with officials of the United States or other foreign governments, or participation in training and related activities funded or arranged by the United States Government;"],[2,"(E) any activity related to legal representation—"],[3,"(i) for matters related to activities described in this paragraph;"],[3,"(ii) for the purpose of adjudicating or resolving claims filed in courts of the United States; or"],[3,"(iii) to comply with this subsection; or"],[2,"(F) any personal or official activities conducted ancillary to activities listed under this paragraph."],[1,"(4) Rule of construction.—Notwithstanding any other law (including any treaty), any office, headquarters, premises, or other facility or establishment within the territory of the United States that is not specifically exempted by paragraph (3)(A) shall be considered to be in the United States for purposes of paragraph (1)(B)."],[1,"(5) Defined term.—In this subsection, the term \"defendant\" means—"],[2,"(A) the Palestinian Authority;"],[2,"(B) the Palestine Liberation Organization;"],[2,"(C) any organization or other entity that is a successor to or affiliated with the Palestinian Authority or the Palestine Liberation Organization; or"],[2,"(D) any organization or other entity that—"],[3,"(i) is identified in subparagraph (A), (B), or (C); and"],[3,"(ii) self identifies as, holds itself out to be, or carries out conduct in the name of, the \"State of Palestine\" or \"Palestine\" in connection with official business of the United Nations."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2334?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2334. Jurisdiction and venue","tname":"Crimes and Criminal Procedure","by":{"1":"4, 13, 21, 12, 13, 18, 27, 29, 30, 13, 14, 13, 15, 16, 41, 42, 13, 13","2":"7, 33, 37, 38, 68, 71, 73, 76","3":"2, 22, 8, 10, 11, 8, 11, 11, 20","4":"13"}},{"t":"usc","label":"22 U.S.C. § 286w","url":"https://www.law.cornell.edu/uscode/text/22/286w","stext":{"head":"§286w. Denial of membership or other status in Fund for Palestine Liberation Organization; United States participation in Fund if membership or other status granted; report by President to Congress","paras":[[0,"It is the policy of the United States that the Palestine Liberation Organization should not be given membership in the Fund or be given observer status or any other official status at any meeting sponsored by or associated with the Fund. The United States Executive Director of the Fund shall promptly notify the Fund of such policy."],[0,"In the event that the Fund provides either membership, observer status, or any other official status to the Palestine Liberation Organization, such action would result in a serious diminution of United States support. Upon review of such action, the President would be required to report his recommendations to the Congress with regard to any further United States participation in the Fund."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/286w?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§286w. Denial of membership or other status in Fund for Palestine Liberation Organization; United States participation in Fund if membership or other status granted; report by President to Congress","tname":"Foreign Relations and Intercourse","by":{"1":"35"}},{"t":"usc","label":"22 U.S.C. § 2227","url":"https://www.law.cornell.edu/uscode/text/22/2227","subs":["(a)"],"by":{"1":"35"}},{"t":"usc","label":"22 U.S.C. § 2378c","url":"https://www.law.cornell.edu/uscode/text/22/2378c","subs":["(a)"],"stext":{"head":"§2378c. Limitation on assistance for the West Bank and Gaza","paras":[[0,"(a) Limitation"],[0,"Assistance may be provided under this chapter to nongovernmental organizations for the West Bank and Gaza only during a period for which a certification described in section 2378b(b) of this title is in effect with respect to the Palestinian Authority."],[0,"(b) Exceptions"],[0,"Subsection (a) shall not apply with respect to the following:"],[0,"(1) Assistance to meet basic human needs"],[1,"Assistance to meet food, water, medicine, health, or sanitation needs, or other assistance to meet basic human needs."],[0,"(2) Assistance to promote democracy"],[1,"Assistance to promote democracy, human rights, freedom of the press, non-violence, reconciliation, and peaceful coexistence, provided that such assistance does not directly benefit Hamas or any other foreign terrorist organization."],[0,"(3) Assistance for individual members of the Palestinian Legislative Council"],[1,"Assistance, other than funding of salaries or salary supplements, to individual members of the Palestinian Legislative Council who the President determines are not members of Hamas or any other foreign terrorist organization, for the purposes of facilitating the attendance of such members in programs for the development of institutions of democratic governance, including enhancing the transparent and accountable operations of such institutions, and providing support for the Middle East peace process."],[0,"(4) Other types of assistance"],[1,"Any other type of assistance if the President—"],[2,"(A) determines that the provision of such assistance is in the national security interest of the United States; and"],[2,"(B) not less than 30 days prior to the obligation of amounts for the provision of such assistance—"],[3,"(i) consults with the appropriate congressional committees regarding the specific programs, projects, and activities to be carried out using such assistance; and"],[3,"(ii) submits to the appropriate congressional committees a written memorandum that contains the determination of the President under subparagraph (A)."],[0,"(c) Marking requirement"],[0,"Assistance provided under this chapter to nongovernmental organizations for the West Bank and Gaza shall be marked as assistance from the American people or the United States Government unless the Secretary of State or, as appropriate, the Administrator of the United States Agency for International Development, determines that such marking will endanger the lives or safety of persons delivering such assistance or would have an adverse effect on the implementation of that assistance."],[0,"(d) Congressional notification"],[0,"Assistance made available under this chapter to nongovernmental organizations for the West Bank and Gaza may not be provided until 15 days after the date on which the President has provided notice thereof to the Committee on International Relations and the Committee on Appropriations of the House of Representatives and to the Committee on Foreign Relations and the Committee on Appropriations of the Senate in accordance with the procedures applicable to reprogramming notifications under section 2394–1(a) of this title."],[0,"(e) Definitions"],[0,"In this section:"],[0,"(1) Appropriate congressional committees"],[1,"the 1 term \"appropriate congressional committees\" means—"],[2,"(A) the Committee on International Relations and the Committee on Appropriations of the House of Representatives; and"],[2,"(B) the Committee on Foreign Relations and the Committee on Appropriations of the Senate."],[0,"(2) Foreign terrorist organization"],[1,"The term \"foreign terrorist organization\" means an organization designated as a foreign terrorist organization by the Secretary of State in accordance with section 1189(a) of title 8."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/2378c?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2378c. Limitation on assistance for the West Bank and Gaza","tname":"Foreign Relations and Intercourse","by":{"1":"35"}},{"t":"usc","label":"28 U.S.C. § 2403","url":"https://www.law.cornell.edu/uscode/text/28/2403","subs":["(a)"],"stext":{"head":"§2403. Intervention by United States or a State; constitutional question","paras":[[0,"(a) In any action, suit or proceeding in a court of the United States to which the United States or any agency, officer or employee thereof is not a party, wherein the constitutionality of any Act of Congress affecting the public interest is drawn in question, the court shall certify such fact to the Attorney General, and shall permit the United States to intervene for presentation of evidence, if evidence is otherwise admissible in the case, and for argument on the question of constitutionality. The United States shall, subject to the applicable provisions of law, have all the rights of a party and be subject to all liabilities of a party as to court costs to the extent necessary for a proper presentation of the facts and law relating to the question of constitutionality."],[0,"(b) In any action, suit, or proceeding in a court of the United States to which a State or any agency, officer, or employee thereof is not a party, wherein the constitutionality of any statute of that State affecting the public interest is drawn in question, the court shall certify such fact to the attorney general of the State, and shall permit the State to intervene for presentation of evidence, if evidence is otherwise admissible in the case, and for argument on the question of constitutionality. The State shall, subject to the applicable provisions of law, have all the rights of a party and be subject to all liabilities of a party as to court costs to the extent necessary for a proper presentation of the facts and law relating to the question of constitutionality."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2403?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2403. Intervention by United States or a State; constitutional question","tname":"Judiciary and Judicial Procedure","by":{"1":"14"}},{"t":"case","label":"Am. Ins. Ass’n v. Garamendi","cite":"539 U.S. 396","y":2003,"id":"2002/02-722","sc":1,"op":1,"sum":"The Court held that California's HVIRA interferes with the president's ability to conduct the nation's foreign policy and is therefore preempted. The Court reasoned that an exercise of state power that concerns foreign relations must yield to the Federal Government's policy or that generally there is executive authority to decide what policy should be implemented.","sumSrc":"Oyez","by":{"2":"45"}},{"t":"case","label":"Am. Nat. Bank & Tr. Co. of Chicago v. Haroco, Inc.","cite":"473 U.S. 606","y":1985,"id":"1984/84-822","sc":1,"sum":"In respondents' private civil action brought under the Racketeer Influenced and Corrupt Organizations Act (RICO), 18 U. S. C. §§ 1961-1968, they alleged that petitioner bank and several of its officers had fraudulently charged excessive interest rates on loans to respondents, and that the scheme to defraud, which was carried on through the mails, violated § 1962(c), in that the mailings constituted a pattern …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"43"}},{"t":"case","label":"Armstrong v. Pomerance","cite":"423 A.2d 174","y":1980,"court":"Del.","url":"https://www.courtlistener.com/c/A.2d/423/174/","by":{"2":"25, 26"}},{"t":"case","label":"Bowman v. Middleton","cite":"1 Bay 252","y":1792,"url":"https://www.courtlistener.com/c/Bay/1/252/","sum":"Holding that law was “against common right, as well as against Magna Charta”.","sumSrc":"brief:2","by":{"2":"57"}},{"t":"case","label":"Calder v. Bull","cite":"3 U.S. 386","y":1798,"id":"1789-1850/3us386","sc":1,"op":2,"sum":"The Court held that the legislation was not an ex post facto law. The Court drew a distinction between criminal rights and \"private rights,\" arguing that restrictions against ex post facto laws were not designed to protect citizens' contract rights. Justice Chase noted that while all ex post facto laws are retrospective, all retrospective laws are not necessarily ex post facto.","sumSrc":"Oyez","by":{"2":"67"}},{"t":"case","label":"California State Automobile Association Inter-Insurance Bureau v. Maloney","cite":"341 U.S. 105","y":1951,"id":"scdb/1950-065","sc":1,"sum":"As applied to appellant, the statute does not violate the Due Process Clause of the Fourteenth Amendment. Pp. 106-111. 96 Cal. App. 2d 876, 216 P. 2d 882, affirmed. A California court sustained the California Compulsory Assigned Risk Law, Cal. Stat. 1947, c. 39, p. 525, as amended, against a claim that it violated the Due Process Clause of the Fourteenth Amendment. 96 Cal. App. 2d 876, 216 P. 2d 882. On appeal to …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"53"}},{"t":"case","label":"City of Boerne v. Flores","cite":"521 U.S. 507","y":1997,"id":"1996/95-2074","sc":1,"sum":"The Court ruled that Congress exceeded its Fourteenth Amendment powers when it enacted the Religious Freedom Restoration Act, subjecting local ordinance to federal regulation.","sumSrc":"Oyez","by":{"2":"44-45, 69","4":"20"}},{"t":"case","label":"Cohens v. Virginia","cite":"19 U.S. 264","y":1821,"id":"1789-1850/19us264","sc":1,"sum":"The Court decided it had jurisdiction over all cases involving Constitutional questions, including state supreme court decisions.","sumSrc":"Oyez","by":{"2":"62"}},{"t":"case","label":"Dickerson v. United States","cite":"530 U.S. 428","y":2000,"id":"1999/99-5525","sc":1,"sum":"The Court held that Congress cannot legislatively overrule Miranda v. Arizona.","sumSrc":"Oyez","by":{"2":"69","4":"20"}},{"t":"case","label":"Fletcher v. Peck","cite":"10 U.S. 87","y":1810,"id":"1789-1850/10us87","sc":1,"sum":"The Court held that a contract is still binding and enforceable, even if secured illegally.","sumSrc":"Oyez","by":{"2":"70"}},{"t":"case","label":"Gilson v. Republic of Ire.","cite":"682 F.2d 1022","y":1982,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/682/1022/","by":{"2":"45"}},{"t":"case","label":"Goodyear Dunlop Tires Operations, S.A. v. Brown","cite":"564 U.S. 915","y":2011,"id":"2010/10-76","sc":1,"op":5,"sum":"The Court held that a consumer cannot sue a manufacturer in a U.S. court when the manufacturer's only connection with the U.S. is that another company sells its products in the country.","sumSrc":"Oyez","by":{"2":"15, 67"}},{"t":"case","label":"GSS Grp. Ltd. v. Nat’l Port Auth.","cite":"680 F.3d 805","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/680/805/","by":{"2":"54"}},{"t":"case","label":"Hammond Packing Co. v. Arkansas","cite":"212 U.S. 322","y":1909,"id":"scdb/1908-081","sc":1,"sum":"The right of a State to prevent foreign corporations from continuing to do business.within its borders, is the correlative of its right to exclude them therefrom; and, as this power is plenary, the State, so long as no contract is impaired, may exert it from consideration of acts done in another jurisdiction.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"21","4":"18"}},{"t":"case","label":"Herederos De Roberto Gomez Cabrera v. Teck Res. Ltd.","cite":"43 F.4th 1303","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/43/1303/","by":{"2":"49","4":"9"}},{"t":"case","label":"Holden v. James","cite":"11 Mass. 396","y":1814,"url":"https://www.courtlistener.com/c/Mass./11/396/","by":{"2":"67-68"}},{"t":"case","label":"Hoover v. Ronwin","cite":"466 U.S. 558","y":1984,"id":"1983/82-1474","sc":1,"sum":"The District Court properly dismissed the complaint for failure to state a claim on which relief could be granted.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"55"}},{"t":"case","label":"Hovey v. Elliott","cite":"167 U.S. 409","y":1897,"id":"scdb/1896-208","sc":1,"sum":"It is not within the power of the Supreme Court of the District of Columbia to order the answer of the defendant in a chancery suit pending in that court to be stricken from the files, and a decree to be entered that the bill be taken pro confesso against him, simply because he was held to be guilty of contempt in neglecting to pay into.court money held by him which was the subject of controversy in the suit, and …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"13, 21","3":"5","4":"18"}},{"t":"case","label":"Jecker v. Montgomery","cite":"54 U.S. 498","y":1851,"id":"scdb/1851-059","sc":1,"sum":"During the war with Mexico, the Admittance, an American vessel, was seized in a port of California, by the commander of avessel of war of the United States,. upon suspicion of trading with the enemy. She was condemned as a lawful prize by. the chaplain belonging to one of the vessels of war upon that station, who had been authorized by the President of the United States to exercise admiralty jurisdiction in cases of …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"64"}},{"t":"case","label":"Joint Anti-Fascist Refugee Committee v. McGrath","cite":"341 U.S. 123","y":1951,"id":"scdb/1950-068","sc":1,"sum":"The judgments are reversed and the cases are remanded to the District Court with instructions to deny the motions that the complaints be dismissed for failure to state claims upon which relief could be granted. Pp. 124-125, 142. 85 U. S. App. D. C. 255, 177 F. 2d 79; 86 U. S. App. D. C. 287, 182 F. 2d 368, reversed. Opinion of BURTON, J. For the opinions of the Justices constituting the majority of the Court, see: …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"54"}},{"t":"case","label":"Kibbe v. Kibbe","cite":"1 Kirby 119","y":1786,"court":"Conn. Super. Ct.","url":"https://www.courtlistener.com/c/Kirby/1/119/","op":1,"sum":"Concluding that a Massachusetts court lacked “legal jurisdiction of the cause” and thus rejecting Page Proof Pending Publication creditors' attempt to have the court recognize out-of-state judgment.","sumSrc":"opinion","by":{"2":"62"}},{"t":"case","label":"Kisor v. Wilkie","cite":"588 U.S. 558","y":2019,"id":"2018/18-15","sc":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"70"}},{"t":"case","label":"Klieman v. Palestinian Auth.","cite":"923 F.3d 1115","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/923/1115/","sum":"Holding alleged “campaign” to “influence” U.S. foreign policy “through the use of U.S. offices, fundraising, lobbying, [and] speaking engagements” insufficient.","sumSrc":"brief:2","by":{"2":"74"}},{"t":"case","label":"Laker Airways v. Sabena, Belgian World Airlines","cite":"731 F.2d 909","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/731/909/","by":{"2":"30"}},{"t":"case","label":"Levine v. PLO","cite":"688 F. Supp. 3d 1001","y":2023,"court":"D. Colo.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/688/1001/","by":{"2":"8"}},{"t":"case","label":"Licci v. Lebanese Canadian Bank","cite":"732 F.3d 161","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/732/161/","by":{"2":"46"}},{"t":"case","label":"Litecubes, LLC v. N. Light Prods.","cite":"523 F.3d 1353","y":2008,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/523/1353/","by":{"2":"30"}},{"t":"case","label":"Mendelsohn v. Meese","cite":"695 F. Supp. 1474","y":1988,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./695/1474/","by":{"2":"37"}},{"t":"case","label":"Merrill v. Sherburne","cite":"1 N.H. 199","y":1818,"url":"https://www.courtlistener.com/c/N.H./1/199/","by":{"2":"68, 70"}},{"t":"case","label":"Mills v. Duryee","cite":"11 U.S. 481","y":1813,"id":"scdb/1813-029","sc":1,"sum":"By the constitution Of the United States, art. 4, sect. 4, it is declared, that full faith and credit shall be ((given, in each state, to the public acts, records and “judicial proceedings of every other state. And the Congress may, by general laws, prescribe the manner “ in which such acts, records and proceedings shall be “ proved, and the effect thereof”","sumSrc":"Headnote (U.S. Reports)","by":{"2":"58"}},{"t":"case","label":"Mohamad v. Palestinian Auth.","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"sum":"The Court held that the word \"individual\" in the Torture Victim Protection Act means a natural person and does not impose any liability against organizations.","sumSrc":"Oyez","by":{"2":"50, 53"}},{"t":"case","label":"Murray’s Lessee v. Hoboken Land & Imp. Co.","cite":"59 U.S. 272","y":1855,"id":"1850-1900/59us272","sc":1,"sum":"The Court found that \"due process of law\" meant that all citizens be tried \"by the law of the land,\" a concept established by the Magna Carta.","sumSrc":"Oyez","by":{"2":"56, 58"}},{"t":"case","label":"Mwani v. Bin Laden","cite":"417 F.3d 1","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/417/1/","by":{"2":"46"}},{"t":"case","label":"Nat’l Equip. Rental, Ltd. v. Szukhent","cite":"375 U.S. 311","y":1964,"id":"1963/81","sc":1,"sum":"Prompt notice to the respondents having been given, Florence Weinberg was their \"agent authorized by appointment\" to receive process within the meaning of Federal Rule of Civil Procedure 4 (d) (1).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18","4":"15"}},{"t":"case","label":"Nat’l Fed’n of Indep. Bus. v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"O’Bannon v. Town Ct. Nursing Ctr.","cite":"447 U.S. 773","y":1980,"id":"1979/78-1318","sc":1,"sum":"The patients have no interest in receiving benefits for care in a particular facility that entitles them, as a matter of constitutional law, to a hearing before HEW and DPW can decertify that facility. Whatever legal rights the patients may have against the nursing home for failing to maintain its status as a qualified nursing home, the enforcement by HEW and DPW of their valid regulations did not directly affect …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"56"}},{"t":"case","label":"Owen v. Miller","cite":"10 Ohio St. 136","y":1859,"url":"https://www.courtlistener.com/c/Ohio%20St./10/136/","by":{"2":"63"}},{"t":"case","label":"Roell v. Withrow","cite":"538 U.S. 580","y":2003,"id":"2002/02-69","sc":1,"sum":"The Court held that consent to a magistrate judge's designation can be inferred from a party's conduct during litigation.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Rose v. Himely","cite":"8 U.S. 241","y":1808,"id":"scdb/1808-001","sc":1,"op":3,"sum":"Jurisdiction of foreign court of admvralty.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"62"}},{"t":"case","label":"Shatsky v. PLO","cite":"2022 WL 826409","y":2022,"court":"S.D.N.Y. Mar. 18","by":{"2":"8"}},{"t":"case","label":"Sokolow v. PLO","cite":"584 U.S. 915","y":2018,"url":"https://supreme.justia.com/cases/federal/us/584/915/","sc":1,"op":2,"by":{"2":"6, 69"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"2":"65"}},{"t":"case","label":"Springfield v. Kibbe","cite":"480 U.S. 257","y":1987,"id":"1986/85-1217","sc":1,"op":2,"sum":"The writ of certiorari is dismissed as improvidently granted. Although petitioner argues here that a heightened negligence standard does not suffice under Monell's requirement of a municipal policy, this Court ordinarily will not decide questions not raised or litigated in the lower courts, especially where the party seeking to argue the issue has failed to object to a jury instruction, as required by Rule 51 of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"55"}},{"t":"case","label":"Swenson v. Thibaut","cite":"250 S.E.2d 279","y":1978,"court":"N.C. Ct. App.","url":"https://www.courtlistener.com/c/S.E.2d/250/279/","by":{"2":"26"}},{"t":"case","label":"Talbot v. Jansen","cite":"3 U.S. 133","y":1795,"id":"scdb/1795-006","sc":1,"op":2,"sum":"THIS was a Writ of Error, in the nature of an Appeal, from the Circuit Court for the District of South Carolina; and the following circumstances appeared upon the pleadings:— A Libel was filed against Edward Ballard, Captain of an armed vessel, called L' Ami de la Liberte, on the Admiralty side of the District Court of South Carolina, in June, 1794, by Joost Janson, late master of the Brigantine Magdalena (then …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"64"}},{"t":"case","label":"Taylor v. Porter & Ford","cite":"4 Hill 140","y":1843,"court":"N.Y. Sup. Ct.","url":"https://www.courtlistener.com/c/Hill/4/140/","by":{"2":"57"}},{"t":"case","label":"The Schooner Exch. v. McFaddon","cite":"11 U.S. 116","y":1812,"id":"scdb/1812-014","sc":1,"op":2,"sum":"Present...dllljke judges.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"59, 62"}},{"t":"case","label":"Toland v. Sprague","cite":"37 U.S. 300","y":1838,"id":"scdb/1838-004","sc":1,"op":3,"ar":4,"sum":"Process of foreign attachment cannot-be properly issued by the circuit courts of the United States, in cases where the defendant is domiciled abroad, or not found. within the district in which the process issues, so that it can be served upon him.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"61-62"}},{"t":"case","label":"United States v. Alvarez-Machain","cite":"504 U.S. 655","y":1992,"id":"1991/91-712","sc":1,"sum":"The fact of respondent's forcible abduction does not prohibit his trial in a United States court for violations of this country's criminal laws.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"53"}},{"t":"case","label":"United States v. Sanchez","cite":"972 F.3d 156","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/972/156/","by":{"2":"52"}},{"t":"case","label":"United States v. Yunis","cite":"924 F.2d 1086","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/924/1086/","by":{"2":"53"}},{"t":"case","label":"Vanzant v. Waddel","cite":"10 Tenn. 260","y":1829,"url":"https://www.courtlistener.com/c/Tenn./10/260/","by":{"2":"67"}},{"t":"case","label":"Wuchter v. Pizzutti","cite":"276 U.S. 13","y":1928,"id":"scdb/1927-088","sc":1,"sum":"1. A state statute which provides that in actions by residents of the State against non-residents for personal injuries resulting from the operation by the latter of their motor vehicles on the state highways, service of summons may be made on the Secretary of State, as their agent, and which contains no further provision making it reasonably probable that notice of such service will be communicated to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24","3":"6"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"2":"54"}},{"t":"case","label":"Zylstra v. Corp. of City of Charleston","cite":"1 Bay 382","y":1794,"url":"https://www.courtlistener.com/c/Bay/1/382/","by":{"2":"57"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(h)"],"by":{"2":"19"}},{"t":"rule","label":"Fed. R. Civ. P. 4","url":"https://www.law.cornell.edu/rules/frcp/rule_4","subs":["(k)(2)(B)"],"by":{"2":"51"}},{"t":"case","label":"Attorney Gen. v. Soto-Lopez","cite":"476 U.S. 898","y":1986,"id":"1985/84-1803","sc":1,"sum":"The judgment is affirmed. 755 F. 2d 266, affirmed. JUSTICE BRENNAN, joined by JUSTICE MARSHALL, JUSTICE BLACKMUN, and JUSTICE POWELL, concluded that the prior resident requirement of the New York civil service veterans' preference laws violates appellees' constitutionally protected right to travel and to equal protection of the law.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"15"}},{"t":"case","label":"Bristol-Meyers Squibb Co. v. Superior Ct.","cite":"582 U.S. 255","y":2017,"url":"https://supreme.justia.com/cases/federal/us/582/255/","sc":1,"op":5,"by":{"3":"14"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"3":"13","4":"20, 21"}},{"t":"case","label":"(I) Cases—Continued: Hernandez v. Mesa","cite":"589 U.S. 93","y":2020,"url":"https://supreme.justia.com/cases/federal/us/589/93/","sc":1,"by":{"3":"13, 21"}},{"t":"case","label":"Lockerty v. Phillips","cite":"319 U.S. 182","y":1943,"id":"scdb/1942-149","sc":1,"sum":"1. The Emergency Price Control Act of 1942 sets up a procedure whereby any person subject to any regulation or order promulgated under the Act may on \"protest\" of the regulation or order secure its review by the Administrator; and, if the protest is denied, the Act confers on the Emergency Court (and on the Supreme Court upon review of decisions of the Emergency Court) equity jurisdicLOCKERTY v. PHILLIPS. Counsel …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"23"}},{"t":"case","label":"Pennoyer v. Neff","cite":"95 U.S. 714","y":1878,"id":"scdb/1877-123","sc":1,"op":1,"ar":2,"sum":"1. A statute of Oregon, after providing for service of summons upon parties or their representatives, personally or at their residence, declares that when service cannot be thus made, and the defendant, after due diligence, eann.ot be found within the State, and “ that fact appears, by affidavit, to the satisfaction of the court or judge thereof, and it, in like manner, appears that a cause of action exists against …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"Plaut v. Spendthrift Farm, Inc.","cite":"514 U.S. 211","y":1995,"id":"1994/93-1121","sc":1,"op":2,"sum":"The Court concluded that Congress had usurped power assigned to the judiciary by Article III and thus had violated the separation of powers principle.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Republic of Iraq v. Beaty","cite":"556 U.S. 848","y":2009,"id":"2008/07-1090","sc":1,"by":{"3":"10"}},{"t":"case","label":"TikTok Inc. v. Garland","cite":"145 S. Ct. 57","y":2025,"id":"2024/24-656","sc":1,"sum":"The challenged provisions of the Protecting Americans from Foreign Adversary Controlled Applications Act, 138 Stat. 955, do not violate petitioners’ First Amendment rights.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"20, 21"}},{"t":"case","label":"Toll v. Moreno","cite":"458 U.S. 1","y":1982,"id":"1981/80-2178","sc":1,"sum":"The University of Maryland's policy of categorically denying domiciled nonimmigrant aliens who hold G-4 visas (visas issued to nonimmigrant aliens who are officers or employees of certain international organizations and to members of their immediate families) in-state status under which preferential treatment is given to domiciled citizen and immigrant alien students for purposes of tuition and fees, is invalid …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"19"}},{"t":"case","label":"United States v. Guest","cite":"383 U.S. 745","y":1966,"id":"1965/65","sc":1,"op":1,"sum":"The Court held that if a state participates at all in a conspiracy affecting an individual's right of free interstate passage, it has violated the Fourteenth Amendment with regard to any individuals whose rights are infringed, based on the constitutional right to travel.","sumSrc":"Oyez","by":{"3":"10"}},{"t":"case","label":"United States v. Morrison","cite":"529 U.S. 598","y":2000,"id":"1999/99-5","sc":1,"sum":"The Court found that sections of the Violence Against Women Act were unconstitutional under the Commerce Clause.","sumSrc":"Oyez","by":{"3":"23"}},{"t":"case","label":"York v. Texas","cite":"137 U.S. 15","y":1890,"id":"scdb/1890-002","sc":1,"op":7,"ar":5,"sum":"The provisions in.the Revised Statutes of Texas, Articles 1242-1245, which, as construed by the highest court of the State, convert an appearance by a defendant for the sole purpose of quéstioning the jurisdiction of the court, into a general appearance and submission to the jurisdiction of the court, do not violate the provision in the Fourteenth Amendment to the Constitution which forbids a State to deprive any …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"7"}},{"t":"const","label":"Article III, Section 1","clauses":[["judicial-vesting","Judicial Vesting Clause"]],"text":"The judicial Power of the United States, shall be vested in one supreme Court, and in such inferior Courts as the Congress may from time to time ordain and establish. The Judges, both of the supreme and inferior Courts, shall hold their Offices during good Behaviour, and shall, at stated Times, receive for their Services, a Compensation, which shall not be diminished during their Continuance in Office.","by":{"3":"23"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"3":"15"}},{"t":"usc","label":"28 U.S.C. § 1330","url":"https://www.law.cornell.edu/uscode/text/28/1330","by":{"3":"10"}},{"t":"law","label":"Justice Against Sponsors of Terrorism Act, Pub. L. No. 114-222","url":"https://www.govinfo.gov/link/plaw/114/public/222","by":{"3":"18"}},{"t":"usc","label":"22 U.S.C. § 8772","url":"https://www.law.cornell.edu/uscode/text/22/8772","by":{"3":"22"}},{"t":"usc","label":"22 U.S.C. § 9402","url":"https://www.law.cornell.edu/uscode/text/22/9402","subs":["(b)(5)"],"by":{"3":"20"}},{"t":"case","label":"Cleveland Bd. of Educ. v. LaFleur","cite":"414 U.S. 632","y":1974,"id":"1973/72-777","sc":1,"sum":"The Court held that the school boards' regulations requiring pregnant teachers to stop working after the fifth month of their pregnancies violated the Fourteenth Amendment's due process clause.","sumSrc":"Oyez","by":{"4":"16"}},{"t":"case","label":"Cnty. of Sacramento v. Lewis","cite":"523 U.S. 833","y":1998,"id":"1997/96-1337","sc":1,"sum":"In a unanimous decision the Court first ruled that the Fourth Amendment's reasonableness standards prevented its illegal seizure protections from applying to high-speed police chases. Such incidents are merely pursuits and do not constitute actual seizures, especially if they fail due to the death of the subject.","sumSrc":"Oyez","by":{"4":"12"}},{"t":"case","label":"Crosby v. United States","cite":"506 U.S. 255","y":1993,"id":"1992/91-6194","sc":1,"sum":"Rule 43 prohibits the trial in absentia of a defendant who is not present at the beginning of trial. The Rule's express use of the limiting phrase \"except as otherwise provided\" clearly indicates that the list of situations in which the trial may proceed without the defendant is exclusive. Moreover, the Rule is a restatement of the law that existed at the time it was adopted in 1944. Its distinction between flight …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"10"}},{"t":"case","label":"DeMore v. Kim","cite":"538 U.S. 510","y":2003,"id":"2002/01-1491","sc":1,"sum":"The Court held, 6-3, that the Immigration and Nationality Act does not deprive the federal courts of jurisdiction to grant habeas relief to aliens challenging their detention under section 1226(c) and, 5-4, that detention during removal proceedings is a constitutionally permissible part of that process.","sumSrc":"Oyez","by":{"4":"16"}},{"t":"case","label":"Logan v. Zimmerman Brush Co.","cite":"455 U.S. 422","y":1982,"id":"1981/80-5950","sc":1,"sum":"The judgment is reversed, and the case is remanded. 82 Ill. 2d 99, 411 N. E. 2d 277, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"18"}},{"t":"case","label":"Michael H. v. Gerald D.","cite":"491 U.S. 110","y":1989,"id":"1988/87-746","sc":1,"op":1,"sum":"Based on its analysis of common-law tradition, the plurality opinion found that a possible biological father does not have a fundamental right to obtain parental rights after the presumptive father has exercised significant responsibility over the child. Therefore due process protection does not apply.","sumSrc":"Oyez","by":{"4":"16"}},{"t":"case","label":"Morrison v. Nat’l Australia Bank, Ltd.","cite":"561 U.S. 247","y":2010,"id":"2009/08-1191","sc":1,"op":3,"sum":"The Court held that the Securities and Exchange Act does not provide a cause of action against foreign plaintiffs suing foreign and American defendants for misconduct in connection with securities traded on foreign stock exchanges.","sumSrc":"Oyez","by":{"4":"3, 16"}},{"t":"case","label":"Palestine Info. Off. v. Shultz","cite":"853 F.2d 932","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/853/932/","by":{"4":"13"}},{"t":"case","label":"Republic of Austria v. Altmann","cite":"541 U.S. 677","y":2004,"id":"2003/03-13","sc":1,"sum":"In a 6-to-3 decision written by Justice John Paul Stevens, the Court ruled that, while the Foreign Sovereign Immunities Act of 1976 does not explicitly state that it should be applied to actions that took place before its passage, there are strong indications in the text of the statute that Congress intended it to apply retroactively.","sumSrc":"Oyez","by":{"4":"11"}},{"t":"case","label":"Turkiye Halk Bankasi A.S. v. United States","cite":"598 U.S. 264","y":2023,"id":"2022/21-1450","sc":1,"sum":"The District Court has jurisdiction of this criminal prosecution under 18 U. S. C. §3231, and the Foreign Sovereign Immunities Act’s comprehensive scheme governing claims of immunity in civil actions against foreign states and their instrumentalities does not cover criminal cases.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"10"}},{"t":"case","label":"Village of Willowbrook v. Olech","cite":"528 U.S. 562","y":2000,"id":"1999/98-1288","sc":1,"sum":"The Court held that Olech's allegations were sufficient to state a claim for relief under traditional equal protection analysis. \"Our cases have recognized successful equal protection claims brought by a 'class of one,' where the plaintiff alleges that she has been intentionally treated differently from others similarly situated and that there is no rational basis for the difference in treatment,\" stated the unanimous, unsigned opinion.","sumSrc":"Oyez","by":{"4":"5"}},{"t":"case","label":"Weinberger v. Salfi","cite":"422 U.S. 749","y":1975,"id":"1974/74-214","sc":1,"sum":"After her husband of less than six months died, appellee widow filed applications for mother's Social Security insurance benefits for herself and child's insurance benefits for her daughter by a previous marriage, but the Social Security Administration (SSA), both initially and on reconsideration at the regional level, denied the applications on the basis of the duration-of-relationship requirements of the Social …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"16, 17"}},{"t":"usc","label":"28 U.S.C. § 1605B","url":"https://www.law.cornell.edu/uscode/text/28/1605B","by":{"4":"11"}},{"t":"usc","label":"31 U.S.C. § 5318","url":"https://www.law.cornell.edu/uscode/text/31/5318","subs":["(k)(3)"],"by":{"4":"14"}}]};